import{waterState,adhState,dialysisState}from './renal-models.js?v=20261023-physicscomplete01';
export function buildRenal(g,T,w={}){let material=c=>new T.MeshStandardMaterial({color:c,roughness:.35}),ball=(p,r,c,name)=>{let m=new T.Mesh(new T.SphereGeometry(r,28,20),material(c));m.position.set(...p);m.name=name;g.add(m);return m;},box=(p,size,c,name)=>{let m=new T.Mesh(new T.BoxGeometry(...size),material(c));m.position.set(...p);m.name=name;g.add(m);};
if(w.kind==='osmosis'){let f=waterState(w.state||'dilute',w.progress??1),m=ball([0,0,0],f.radius/60,0x789fae,'cell-membrane');m.material.transparent=true;m.material.opacity=.3;m.material.depthWrite=false;for(let i=0;i<f.inside;i++)ball([-.35+(i%4)*.22,-.3+Math.floor(i/4)*.25,.1],.06,0xb6d6dd,'cell-water');for(let i=0;i<f.outside;i++)ball([-1.8+(i%3)*.18,-.6+Math.floor(i/3)*.3,.2],.06,0xb6d6dd,'outside-water');return;}
if(w.kind==='urea'){for(let i=0;i<4;i++){let b=ball([-1.65+i*1.1,0,0],.38,i===1?0xdab98e:0xb18a84,['amino-acids','ammonia','urea','kidney-removal'][i]);if(i<3)box([-1.1+i*1.1,0,0],[.3,.04,.04],0xb6ced0,'stage-link');}return;}
let left=w.kind==='filter'?-1.3:-1.1,right=w.kind==='filter'?0:1.1;box([0,0,-.25],[.09,2.1,1.3],0xd9c4a3,'partially-permeable-barrier');let count=w.kind==='adh'?adhState(w.state).recovered:w.kind==='dialysis'?dialysisState(w.progress??1).fluidUrea:6;for(let i=0;i<8;i++)ball([left+(i%2)*.2,-.7+Math.floor(i/2)*.45,.2],i<3&&w.kind!=='adh'?.14:.06,i<3&&w.kind!=='adh'?0xc68d91:0xb8d8de,i<3&&w.kind!=='adh'?'retained-blood-cell':'small-solute');for(let i=0;i<Math.min(10,count);i++)ball([right+.3+(i%2)*.2,-.7+Math.floor(i/2)*.32,.2],.06,0xb8d8de,'transferred-small-unit');if(w.kind==='filter'){box([1.3,0,-.2],[.08,2.1,1.2],0x9bb9bc,'reabsorption-boundary');ball([1.8,-.5,.2],.09,0xe3c08f,'urine-remainder');}}
